contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value, uint _seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // Seed C with some Ether so that the balance can vary, via the owner-only sendMoney to the test contract.
        require(address(this).balance >= _seed);
        c.sendMoney(address(this), _seed, ""); if (__ESBMC_reverted()) return;

        uint balBefore = address(c).balance;

        bool reverted;
        c.withdraw(_value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfter = address(c).balance;

        assert(reverted ? balAfter == balBefore : (balBefore >= _value && balAfter == balBefore - _value));
    }

    receive() external payable {}
}

